DO $$ DECLARE role_name text; signature text; BEGIN
 PERFORM pg_temp.team_check((SELECT relrowsecurity FROM pg_class WHERE oid='pc_private.booking_message_actors'::regclass),'actor RLS');
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
 PERFORM pg_temp.team_check(NOT has_table_privilege(role_name,'pc_private.booking_message_actors','SELECT,INSERT,UPDATE,DELETE'),'no direct actor access');
 PERFORM pg_temp.team_check(NOT has_function_privilege(role_name,'pc_private.centre_message_access(uuid,uuid,uuid,uuid)','EXECUTE'),'helper not client callable');
 END LOOP;
 FOREACH signature IN ARRAY ARRAY['set_centre_message_permission(uuid,boolean,uuid)','get_centre_lesson_messages(uuid,uuid,uuid,uuid,bigint,bigint,integer)','send_centre_lesson_message(uuid,uuid,uuid,uuid,uuid,text)','mark_centre_lesson_messages_read(uuid,uuid,uuid,uuid,bigint)'] LOOP
 PERFORM pg_temp.team_check(NOT has_function_privilege('anon','public.'||signature,'EXECUTE') AND NOT has_function_privilege('service_role','public.'||signature,'EXECUTE'),'no public or service role RPC');
 PERFORM pg_temp.team_check(NOT (SELECT prosecdef FROM pg_proc WHERE oid=('public.'||signature)::regprocedure),'public invoker only');
 END LOOP;
END $$;
